import json
d = json.load(open('/home/azureuser/projects/skills/skills/uipath-maestro-bpmn/validator/bpmn-spec.json'))
et = d['extensionTypes']
types=set()
def walk(o):
    if isinstance(o, dict):
        for k,v in o.items():
            if k=='type' and isinstance(v,str):
                types.add(v)
            walk(v)
    elif isinstance(o, list):
        for i in o:
            walk(i)
walk(et)
print(sorted(types))
